#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <limits.h>

#define MOD 1000000007LL

typedef struct {
    long long a, b;
} Effect;

typedef struct {
    long long a, b;
    long long start;
} HullLine;

static int cmp_effect_slope(const void *pa, const void *pb) {
    const Effect *x = (const Effect *)pa;
    const Effect *y = (const Effect *)pb;
    if (x->a != y->a) return (x->a > y->a) - (x->a < y->a);
    return (x->b > y->b) - (x->b < y->b);
}

static int cmp_meal(const void *pa, const void *pb) {
    const Effect *x = (const Effect *)pa;
    const Effect *y = (const Effect *)pb;

    if (x->a == 1 && y->a != 1) return -1;
    if (x->a != 1 && y->a == 1) return 1;
    if (x->a == 1) return 0;

    long long left = x->b * (y->a - 1);
    long long right = y->b * (x->a - 1);
    if (left != right) return left > right ? -1 : 1;
    return 0;
}

static long long ceil_div(long long n, long long d) {
    long long q = n / d;
    if (n > 0 && n % d != 0) q++;
    return q;
}

static void compose(long long a1, long long b1,
                   long long a2, long long b2,
                   long long *a, long long *b) {
    *a = (a1 * a2) % MOD;
    *b = (a1 * b2 + b1) % MOD;
}

static void apply_repeated(long long a, long long b, long long times,
                           long long *x) {
    long long ra = 1, rb = 0;
    long long ba = a % MOD, bb = b % MOD;

    while (times > 0) {
        if (times & 1LL) {
            long long na, nb;
            compose(ba, bb, ra, rb, &na, &nb);
            ra = na;
            rb = nb;
        }
        long long na, nb;
        compose(ba, bb, ba, bb, &na, &nb);
        ba = na;
        bb = nb;
        times >>= 1;
    }

    *x = (ra * (*x) + rb) % MOD;
}

int main(void) {
    int n, m;
    long long k;

    if (scanf("%d %d %lld", &n, &m, &k) != 3) return 0;

    Effect *spells = (Effect *)malloc((size_t)n * sizeof(Effect));
    Effect *meals = (Effect *)malloc((size_t)m * sizeof(Effect));
    if (!spells || !meals) return 0;

    for (int i = 0; i < n; i++) scanf("%lld", &spells[i].a);
    for (int i = 0; i < n; i++) scanf("%lld", &spells[i].b);

    for (int i = 0; i < m; i++) scanf("%lld", &meals[i].a);
    for (int i = 0; i < m; i++) scanf("%lld", &meals[i].b);

    qsort(spells, n, sizeof(Effect), cmp_effect_slope);

    int unique_count = 0;
    for (int i = 0; i < n; i++) {
        if (unique_count == 0 ||
            spells[i].a != spells[unique_count - 1].a) {
            spells[unique_count++] = spells[i];
        } else if (spells[i].b > spells[unique_count - 1].b) {
            spells[unique_count - 1].b = spells[i].b;
        }
    }

    HullLine *hull = (HullLine *)malloc((size_t)unique_count * sizeof(HullLine));
    if (!hull) return 0;

    int hull_count = 0;
    for (int i = 0; i < unique_count; i++) {
        long long a = spells[i].a;
        long long b = spells[i].b;

        if (hull_count == 0) {
            hull[hull_count].a = a;
            hull[hull_count].b = b;
            hull[hull_count].start = LLONG_MIN;
            hull_count++;
            continue;
        }

        long long start;
        while (1) {
            int last = hull_count - 1;
            start = ceil_div(hull[last].b - b, a - hull[last].a);
            if (hull_count == 1 || start > hull[last].start) break;
            hull_count--;
        }

        hull[hull_count].a = a;
        hull[hull_count].b = b;
        hull[hull_count].start = start;
        hull_count++;
    }

    qsort(meals, m, sizeof(Effect), cmp_meal);

    long long meal_a = 1, meal_b = 0;
    for (int i = 0; i < m; i++) {
        meal_a = meal_a * (meals[i].a % MOD) % MOD;
        meal_b = (meals[i].a % MOD * meal_b + meals[i].b) % MOD;
    }

    int q;
    scanf("%d", &q);

    for (int qi = 0; qi < q; qi++) {
        long long exact_x;
        scanf("%lld", &exact_x);
        long long mod_x = exact_x % MOD;
        long long remaining = k;

        while (remaining > 0) {
            int lo = 0, hi = hull_count;
            while (lo + 1 < hi) {
                int mid = lo + (hi - lo) / 2;
                if (hull[mid].start <= exact_x) lo = mid;
                else hi = mid;
            }
            int idx = lo;

            if (idx == hull_count - 1) {
                apply_repeated(hull[idx].a, hull[idx].b, remaining, &mod_x);
                remaining = 0;
                break;
            }

            long long next_start = hull[idx + 1].start;
            long long a = hull[idx].a;
            long long b = hull[idx].b;

            if (a == 1) {
                long long steps = (next_start - exact_x + b - 1) / b;
                if (steps > remaining) steps = remaining;

                mod_x = (mod_x + (b % MOD) * (steps % MOD)) % MOD;
                exact_x += b * steps;
                remaining -= steps;
            } else {
                while (remaining > 0 && exact_x < next_start) {
                    exact_x = a * exact_x + b;
                    mod_x = (a % MOD * mod_x + b) % MOD;
                    remaining--;
                }
            }
        }

        long long answer = (meal_a * mod_x + meal_b) % MOD;
        printf("%lld\n", answer);
    }

    free(hull);
    free(spells);
    free(meals);
    return 0;
}
